const nav=[['/','工作台'],['/events','活动与展位'],['/products','商品'],['/people','人员与班次'],['/stock','库存'],['/sales','销售工作台'],['/returns','退货与核对'],['/operations','业务办理中心'],['/commissions','佣金'],['/reports','报表'],['/audit','操作日志']];
function QueryFailures(){
  const [messages,setMessages]=useState<string[]>([]);
  useEffect(()=>{const update=()=>setMessages([...new Set(client.getQueryCache().getAll().filter(q=>q.isActive()&&q.state.error).map(q=>q.state.error instanceof Error?q.state.error.message:'数据读取失败'))]);update();return client.getQueryCache().subscribe(update);},[]);
  return messages.length?<div role="alert" className="error">{messages.map(x=><p key={x}>{x}</p>)}</div>:null;
}
function Shell({auth,onLogout}:{auth:Auth;onLogout:()=>void}){
  const path=useLocation().pathname;const [search,setSearch]=useState(''),[refreshing,setRefreshing]=useState(false),[loggingOut,setLoggingOut]=useState(false),[logoutError,setLogoutError]=useState('');
  const searchInput=useRef<HTMLInputElement>(null);
  const visible=auth.user.role==='OWNER'?nav:nav.filter(([url])=>['/','/events','/products','/people','/stock','/sales','/returns','/operations','/commissions','/reports'].includes(url));
  const icons:Record<string,IconName>={'/':'overview','/events':'events','/products':'products','/people':'people','/stock':'stock','/sales':'sales','/returns':'returns','/commissions':'commissions','/reports':'reports','/audit':'audit','/operations':'stock'};
  useEffect(()=>{setSearch('');window.scrollTo({top:0,left:0,behavior:'instant'});document.title=`${visible.find(([url])=>url===path)?.[1]??'工作台'} · Foxcore Retail`;},[path]);
  useEffect(()=>{const handle=(event:KeyboardEvent)=>{if((event.ctrlKey||event.metaKey)&&event.key==='k'){event.preventDefault();searchInput.current?.focus();}};window.addEventListener('keydown',handle);return()=>window.removeEventListener('keydown',handle);},[]);
  const logout=async()=>{if(loggingOut)return;setLoggingOut(true);setLogoutError('');try{await api('/auth/logout',{method:'POST',headers:{'X-CSRF-Token':auth.csrf},body:'{}'});onLogout();}catch(error){setLogoutError(error instanceof Error?error.message:'退出失败，请重试');}finally{setLoggingOut(false);}};
  const content=path==='/events'?<Events auth={auth}/>:path==='/products'?<Products auth={auth}/>:path==='/people'?<People auth={auth}/>:path==='/stock'?<Stock auth={auth}/>:path==='/sales'?<Sales auth={auth}/>:path==='/returns'?<Returns auth={auth}/>:path==='/operations'?<Operations auth={auth}/>:path==='/commissions'?<Commissions auth={auth}/>:path==='/reports'?<Reports auth={auth}/>:path==='/audit'&&auth.user.role==='OWNER'?<Audit/>:<Dashboard auth={auth}/>;
  return <SearchContext.Provider value={{query:search,clear:()=>setSearch('')}}><a className="skip-link" href="#main-content">跳至主要内容</a><div className="shell">
    <aside className="sidebar"><Link to="/" className="logo"><span className="brand-mark small-mark">F<span>•</span></span><span>FOXCORE<small>RETAIL OPERATIONS</small></span></Link><div className="workspace-label"><span className="live-indicator"/>现场零售工作空间</div><div className="nav-caption">WORKSPACE <span>工作区域</span></div>
      <nav aria-label="主导航">{visible.map(([url,label])=><Link key={url} to={url} className={path===url?'active':''} aria-current={path===url?'page':undefined}><Icon name={icons[url]}/><span>{label}</span>{path===url&&<span className="nav-active-dot"/>}</Link>)}</nav>
      <div className="sidebar-note"><Icon name="check" size={16}/><div>每一步，都有迹可循<small>库存 · 单据 · 收款 · 佣金</small></div></div>
      <div className="sidebar-bottom"><div className="profile"><div className="avatar">{auth.user.username.slice(0,1).toUpperCase()}</div><div><strong>{auth.user.username}</strong><small>{auth.user.role==='OWNER'?'管理员 · 全局管理':'员工 · 共享业务记录'}</small></div></div><button className="logout" disabled={loggingOut} onClick={()=>void logout()}><Icon name="logout" size={16}/>{loggingOut?'退出中…':'退出登录'}</button></div>
    </aside>
    <main id="main-content"><header className="topbar"><div className="breadcrumb">Foxcore Retail <span>/</span> <strong>{visible.find(([url])=>url===path)?.[1]??'工作台'}</strong></div><div className="topbar-controls"><label className="page-search"><Icon name="search" size={17}/><span className="sr-only">搜索本页已加载记录</span><input ref={searchInput} value={search} onChange={e=>setSearch(e.target.value)} placeholder="搜索本页已加载记录" type="search"/><kbd>Ctrl K</kbd></label><button className={'refresh-button '+(refreshing?'refreshing':'')} aria-label="刷新服务器数据" title="刷新服务器数据" disabled={refreshing} onClick={async()=>{setRefreshing(true);try{await client.invalidateQueries();}finally{setRefreshing(false);}}}><Icon name="refresh" size={17}/></button><span className="date-label">{new Date().toLocaleDateString('zh-CN',{month:'2-digit',day:'2-digit'})}</span></div></header>
      <div className="content" key={path}>{logoutError&&<div className="error" role="alert">{logoutError}</div>}<CommandRecovery auth={auth}/><QueryFailures/>{search&&<div className="search-context"><Icon name="search" size={16}/><span>正在筛选本页已加载的表格记录：“{search}”<small>未加载的其他分页不包含在搜索内。</small></span><button className="text-button" onClick={()=>setSearch('')}>清除搜索</button></div>}{content}</div>
      <footer className="app-footer"><span>FOXCORE RETAIL</span><span>清晰记录每一笔业务</span><span>按单据币种显示 · 北京时间</span></footer>
    </main>
  </div></SearchContext.Provider>;
}

function App(){const [auth,setAuth]=useState<Auth|null>(null),[ready,setReady]=useState(false);useEffect(()=>{api<Auth|{user:null;csrf:null}>('/auth/me').then(x=>setAuth(x.user?x as Auth:null)).catch(()=>{}).finally(()=>setReady(true));},[]);if(!ready)return <div className="boot">FOXCORE <span>正在连接工作台…</span></div>;if(!auth)return <Login onLogin={setAuth}/>;if(auth.user.mustChangePassword)return <PasswordChange auth={auth} onDone={()=>setAuth(null)}/>;return <BrowserRouter><Shell auth={auth} onLogout={()=>{setAuth(null);client.clear();}}/></BrowserRouter>;}
createRoot(document.getElementById('root')!).render(<QueryClientProvider client={client}><App/></QueryClientProvider>);
